'use strict';
/**
 * icons3d.js - the weather icons of the home-screen widget: a polished 3D set (160 x 160 pictures with transparent surroundings,
 * deflated RGBA, base64). Same call as icons_line.js:
 *   make(icon, day, w, h, size) -> Canvas     icon: a name from weather.describe(); day === false picks the night picture;
 *                                             the icon is `size` wide, centred in a w x h picture
 */
const zlib = require('zlib');
const { Canvas } = require('./kit/canvas');
const N = 160;
const DATA = {
    'clear': '',
    'mostly-clear': '',
    'partly': '',
    'cloudy': '',
    'fog': '',
    'drizzle': '',
    'rain': '',
    'heavy-rain': '',
    'showers': '',
    'sleet': '',
    'snow': '',
    'storm': '',
    'n-clear': '',
    'n-mostly-clear': '',
    'n-partly': '',
    'n-cloudy': ''
};
const NIGHT = { 'clear': 'n-clear', 'mostly-clear': 'n-mostly-clear', 'partly': 'n-partly', 'cloudy': 'n-cloudy', 'showers': 'rain' };
const raw = {};
function pic(name) {
    if (raw[name]) return raw[name];
    const pixels = zlib.inflateSync(Buffer.from(DATA[name], 'base64'));
    // The daylight sun has an opaque brown matte, not merely a low-alpha halo.
    // Remove that dark matte before resampling so it cannot bleed into the rays.
    if (name === 'clear') {
        for (let k = 0; k < pixels.length; k += 4) {
            const edge = Math.max(0, Math.min(1, (pixels[k] - 80) / 90));
            pixels[k + 3] = Math.round(pixels[k + 3] * edge * edge * (3 - 2 * edge));
            if (!pixels[k + 3]) pixels[k] = pixels[k + 1] = pixels[k + 2] = 0;
        }
    }
    return (raw[name] = pixels);
}

/** the picture scaled to s x s (area average over premultiplied colour), into a w x h canvas, centred */
function make(icon, day, w, h, size) {
    const name = (day === false && NIGHT[icon]) || icon, src = pic(DATA[name] ? name : 'cloudy');
    const cv = new Canvas(w, h), s = Math.max(1, Math.round(size)), f = N / s, n = Math.max(1, Math.min(4, Math.ceil(f)));
    const ox = Math.round((w - s) / 2), oy = Math.round((h - s) / 2), d = cv.d;
    for (let y = 0; y < s; y++) {
        const dy = oy + y; if (dy < 0 || dy >= h) continue;
        for (let x = 0; x < s; x++) {
            const dx = ox + x; if (dx < 0 || dx >= w) continue;
            let r = 0, g = 0, b = 0, a = 0;
            for (let j = 0; j < n; j++) {
                const sy = Math.min(N - 1, Math.floor((y + (j + 0.5) / n) * f));
                for (let i = 0; i < n; i++) {
                    const sx = Math.min(N - 1, Math.floor((x + (i + 0.5) / n) * f)), k = (sy * N + sx) * 4, al = src[k + 3];
                    r += src[k] * al; g += src[k + 1] * al; b += src[k + 2] * al; a += al;
                }
            }
            if (a === 0) continue;
            const o = (dy * w + dx) * 4;
            d[o] = Math.round(r / a); d[o + 1] = Math.round(g / a); d[o + 2] = Math.round(b / a); let al8 = a / (n * n);
            // the pictures carry a faint haze around the shape (alpha 8..24); the HMI shows it as a pale square, so fade it out
            if (al8 < 20) al8 = 0; else if (al8 < 56) al8 = al8 * (al8 - 20) / 36;
            d[o + 3] = Math.round(al8);
        }
    }
    return cv;
}
module.exports = { make };
